#include <memory>
#include <iostream>

void bad_print(std::auto_ptr<int> p) {
    if (p.get()) {
        std::cout << "Value: " << *p << std::endl;
    }
    // p is destroyed here, deleting the managed memory
}

int main() {
    std::auto_ptr<int> p(new int);
    *p = 42;
    bad_print(p);  // Ownership transfers, p becomes NULL

    // *p = 18;  // RUNTIME ERROR (Dereferencing null pointer)
    if (!p.get()) {
        std::cout << "Error: Caller's pointer is null.\n";
    }
}
